/* Что библиотека отдаёт наружу.
 *
 * Всё, кроме JNI_OnLoad, обязано быть скрыто. libagloader.so грузится раньше
 * libag-client.so и потому стоит в таблице поиска динамического компоновщика
 * впереди движка. Если наша копия ImGui экспортирует свои символы, вызовы
 * ImGui из самого движка привязываются к ним — движок начинает работать с
 * чужим контекстом и падает. Нативные методы игры мы всё равно ставим через
 * RegisterNatives, а не по именам, так что экспортировать Java_* не нужно.
 */
{
  global:
    JNI_OnLoad;
    JNI_OnUnload;
  local:
    *;
};
